import pytest
from mdinline import render


class TestBasicEmphasis:
    """Test basic emphasis and strong emphasis."""

    def test_single_asterisk_emphasis(self):
        assert render("*hello*") == "<em>hello</em>"

    def test_double_asterisk_strong(self):
        assert render("**hello**") == "<strong>hello</strong>"

    def test_triple_asterisk(self):
        assert render("***hello***") == "<em><strong>hello</strong></em>"

    def test_mixed_emphasis_and_strong(self):
        assert render("*Hello* **world**") == "<em>Hello</em> <strong>world</strong>"

    def test_emphasis_inside_strong(self):
        assert render("**bold *and* italic**") == "<strong>bold <em>and</em> italic</strong>"

    def test_multiple_separate_emphasis(self):
        assert render("*one* and *two*") == "<em>one</em> and <em>two</em>"

    def test_multiple_separate_strong(self):
        assert render("**one** and **two**") == "<strong>one</strong> and <strong>two</strong>"


class TestBackslashEscapes:
    """Test backslash escapes for punctuation."""

    def test_escaped_asterisk_not_emphasis(self):
        assert render(r"\*not emphasis\*") == "*not emphasis*"

    def test_escaped_underscore_not_emphasis(self):
        assert render(r"\_not emphasis\_") == "_not emphasis_"

    def test_escaped_backtick_not_code(self):
        assert render(r"\`not code\`") == "`not code`"

    def test_escaped_various_punctuation(self):
        assert render(r"\!\@\#\$\%") == "!@#$%"

    def test_backslash_before_non_punctuation_is_literal(self):
        assert render(r"\a") == r"\a"

    def test_backslash_at_end_of_line_is_literal(self):
        assert render("test\\") == "test\\"

    def test_escaped_punctuation_in_emphasis(self):
        assert render(r"*\*starred\**") == "<em>*starred*</em>"

    def test_escaped_asterisk_between_text(self):
        assert render("a\\*b") == "a*b"


class TestCodeSpans:
    """Test code spans with various backtick configurations."""

    def test_single_backtick_code_span(self):
        assert render("use `a*b` here") == "use <code>a*b</code> here"

    def test_code_span_with_emphasis_chars_inside(self):
        assert render("`*foo*`") == "<code>*foo*</code>"

    def test_code_span_with_mixed_emphasis_chars(self):
        assert render("`*_~test~_*`") == "<code>*_~test~_*</code>"

    def test_double_backtick_code_span(self):
        assert render("``a ` b``") == "<code>a ` b</code>"

    def test_triple_backtick_code_span(self):
        assert render("```a `` b```") == "<code>a `` b</code>"

    def test_backtick_runs_must_match_length(self):
        # Single backtick doesn't close double backtick
        assert render("``code`") == "``code`"

    def test_code_span_with_leading_trailing_space_trimmed(self):
        assert render("`a b `") == "<code>a b</code>"

    def test_code_span_with_only_spaces_not_trimmed(self):
        assert render("` ` ` `") == "<code> </code> <code> </code>"

    def test_multiple_spaces_trimmed_one_from_each_end(self):
        assert render("`  a  `") == "<code> a </code>"

    def test_code_span_binds_tighter_than_emphasis(self):
        assert render("*a `*` b*") == "<em>a <code>*</code> b</em>"

    def test_backtick_at_start_before_code_span(self):
        assert render("` code`") == "<code>code</code>"

    def test_backtick_at_end_after_code_span(self):
        assert render("`code `") == "<code>code</code>"

    def test_code_span_inside_emphasis(self):
        assert render("*use `code` here*") == "<em>use <code>code</code> here</em>"

    def test_unmatched_backtick_is_plain_text(self):
        assert render("`unclosed") == "`unclosed"

    def test_code_span_at_boundaries(self):
        assert render("`code`") == "<code>code</code>"


class TestHtmlEscaping:
    """Test HTML special character escaping."""

    def test_escape_ampersand(self):
        assert render("a & b") == "a &amp; b"

    def test_escape_less_than(self):
        assert render("a < b") == "a &lt; b"

    def test_escape_greater_than(self):
        assert render("a > b") == "a &gt; b"

    def test_escape_quote(self):
        assert render('a " b') == 'a &quot; b'

    def test_escape_all_special_chars(self):
        assert render("a&b<c>d\"e") == "a&amp;b&lt;c&gt;d&quot;e"

    def test_escape_in_code_span(self):
        assert render("`a & b`") == "<code>a &amp; b</code>"

    def test_escape_in_emphasis(self):
        assert render("*a & b*") == "<em>a &amp; b</em>"

    def test_escape_in_strong(self):
        assert render("**a < b**") == "<strong>a &lt; b</strong>"

    def test_html_is_escaped_not_rendered(self):
        assert render("a < b & c") == "a &lt; b &amp; c"


class TestUnderscoreEmphasis:
    """Test underscore emphasis rules."""

    def test_underscore_emphasis_basic(self):
        assert render("_hello_") == "<em>hello</em>"

    def test_underscore_strong(self):
        assert render("__hello__") == "<strong>hello</strong>"

    def test_underscore_in_word_not_emphasis(self):
        assert render("snake_case_name") == "snake_case_name"

    def test_underscore_at_word_boundaries(self):
        assert render("word _emphasis_ here") == "word <em>emphasis</em> here"

    def test_underscore_after_punctuation_can_open(self):
        assert render("._hello_") == ".<em>hello</em>"

    def test_underscore_before_punctuation_can_close(self):
        assert render("_hello_.") == "<em>hello</em>."

    def test_underscore_mixed_with_asterisk(self):
        assert render("*_mixed_*") == "<em><em>mixed</em></em>"

    def test_underscore_in_middle_of_word_no_emphasis(self):
        assert render("test_case") == "test_case"


class TestComplexCombinations:
    """Test complex combinations of emphasis, code spans, and escapes."""

    def test_code_span_with_escaped_backtick_inside(self):
        # Backslashes inside code spans are literal
        assert render("`test\\`") == "<code>test\\</code>"

    def test_multiple_code_spans_in_emphasis(self):
        assert render("*use `code1` and `code2`*") == "<em>use <code>code1</code> and <code>code2</code></em>"

    def test_nested_emphasis_with_different_delimiters(self):
        assert render("*bold _and italic_ text*") == "<em>bold <em>and italic</em> text</em>"

    def test_escaped_delimiter_between_emphasis(self):
        assert render("*start\\* middle *end*") == "<em>start* middle </em>end*"

    def test_foo_bar_emphasis_rule(self):
        # From spec: *foo**bar* is <em>foo**bar</em>
        assert render("*foo**bar*") == "<em>foo**bar</em>"


class TestMultipleOfThreeRule:
    """Test the multiple of 3 rule for emphasis matching."""

    def test_asterisk_matching_rule_multiple_of_three_cant_match(self):
        # Both runs have length that sum to multiple of 3
        # When both can open and close, they can't match
        assert render("**foo**") == "<strong>foo</strong>"

    def test_triple_asterisk_emphasis_then_strong(self):
        assert render("***hello***") == "<em><strong>hello</strong></em>"

    def test_four_asterisks_strong_then_plain(self):
        assert render("****hello****") == "<strong><strong>hello</strong></strong>"


class TestDelimiterMatching:
    """Test delimiter run matching rules."""

    def test_left_right_flanking_basic(self):
        # Simple case of left-flanking and right-flanking
        assert render("*test*") == "<em>test</em>"

    def test_multiple_runs_left_to_right(self):
        # Matching goes left to right
        assert render("*a* *b* *c*") == "<em>a</em> <em>b</em> <em>c</em>"

    def test_unopened_closer_stays_plain(self):
        # Closer with no matching opener stays as plain text
        assert render("*unopened") == "*unopened"

    def test_unclosed_opener_stays_plain(self):
        # Opener with no closer stays as plain text
        assert render("unclosed*") == "unclosed*"

    def test_strong_then_emphasis_leftover(self):
        # From spec: **a* is *<em>a</em>
        assert render("**a*") == "*<em>a</em>"

    def test_emphasis_then_strong_leftover(self):
        # *a** is <em>a</em>*
        assert render("*a**") == "<em>a</em>*"


class TestWhitespaceHandling:
    """Test whitespace handling."""

    def test_leading_whitespace_preserved(self):
        assert render("  *test*") == "  <em>test</em>"

    def test_trailing_whitespace_preserved(self):
        assert render("*test*  ") == "<em>test</em>  "

    def test_leading_and_trailing_preserved(self):
        assert render("  *test*  ") == "  <em>test</em>  "

    def test_space_around_emphasis(self):
        assert render(" *test* ") == " <em>test</em> "

    def test_tabs_preserved(self):
        assert render("\t*test*\t") == "\t<em>test</em>\t"


class TestInputValidation:
    """Test input validation."""

    def test_newline_raises_error(self):
        with pytest.raises(ValueError):
            render("one\ntwo")

    def test_carriage_return_raises_error(self):
        with pytest.raises(ValueError):
            render("one\rtwo")

    def test_carriage_return_newline_raises_error(self):
        with pytest.raises(ValueError):
            render("one\r\ntwo")

    def test_newline_in_middle_raises_error(self):
        with pytest.raises(ValueError):
            render("start\nmiddle\nend")


class TestPlainText:
    """Test cases where text should remain plain."""

    def test_plain_text_no_special_chars(self):
        assert render("hello world") == "hello world"

    def test_plain_text_with_numbers(self):
        assert render("test123") == "test123"

    def test_single_asterisk_not_emphasis(self):
        assert render("*") == "*"

    def test_unmatched_emphasis_stays_plain(self):
        assert render("test *unmatched") == "test *unmatched"

    def test_backtick_alone_stays_plain(self):
        assert render("`") == "`"

    def test_mixed_unmatched_delimiters(self):
        assert render("*test `code") == "*test `code"


class TestEdgeCases:
    """Test edge cases and boundary conditions."""

    def test_empty_code_span(self):
        # Empty code span is not possible - backticks need content
        assert render("``") == "``"

    def test_whitespace_only_code_span(self):
        assert render("` `") == "<code> </code>"

    def test_code_span_with_newline_like_text(self):
        # Test with text that looks like it might have special meaning
        assert render("`\\n`") == "<code>\\n</code>"

    def test_multiple_consecutive_delimiters(self):
        assert render("****test****") == "<strong><strong>test</strong></strong>"

    def test_emphasis_at_line_start(self):
        assert render("*start") == "*start"

    def test_emphasis_at_line_end(self):
        assert render("end*") == "end*"

    def test_all_delimiters_at_once(self):
        assert render("*_`test`_*") == "<em><em><code>test</code></em></em>"

    def test_punctuation_before_underscore_emphasis(self):
        # Underscore after punctuation can open
        assert render("!_test_") == "!<em>test</em>"

    def test_punctuation_after_underscore_emphasis(self):
        # Underscore before punctuation can close
        assert render("_test_!") == "<em>test</em>!"


class TestSpecExamples:
    """Test examples from the CommonMark spec or README."""

    def test_example_from_readme_1(self):
        assert render("*Hello* **world**") == "<em>Hello</em> <strong>world</strong>"

    def test_example_from_readme_2(self):
        assert render("use `a*b` here") == "use <code>a*b</code> here"

    def test_example_from_readme_3(self):
        assert render("snake_case_name") == "snake_case_name"

    def test_example_from_readme_4(self):
        assert render("**bold *and* italic**") == "<strong>bold <em>and</em> italic</strong>"

    def test_backtick_string_example(self):
        # From spec: ``` ``a ` b`` ``` is a code span containing ``a ` b``
        assert render("``a ` b``") == "<code>a ` b</code>"

    def test_emphasis_code_binding(self):
        # Code spans bind tighter than emphasis
        assert render("*a `*` b*") == "<em>a <code>*</code> b</em>"


class TestCharacterEscaping:
    """Test various punctuation and character escaping."""

    def test_escaped_bracket(self):
        assert render(r"\[bracket\]") == "[bracket]"

    def test_escaped_brace(self):
        assert render(r"\{brace\}") == "{brace}"

    def test_escaped_hash(self):
        assert render(r"\#not a header") == "#not a header"

    def test_escaped_plus(self):
        assert render(r"\+plus") == "+plus"

    def test_escaped_question(self):
        assert render(r"\?question") == "?question"

    def test_all_ascii_punctuation(self):
        # ASCII punctuation characters that can be escaped
        punctuation = "!\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~"
        escaped = "".join(f"\\{c}" for c in punctuation)
        assert render(escaped) == punctuation


class TestComplexEmphasisScenarios:
    """Test complex emphasis scenarios."""

    def test_unmatched_closer_before_opener(self):
        # *_ doesn't match anything, then `_foo_` matches
        assert render("*_foo_") == "*<em>foo</em>"

    def test_multiple_openers_one_closer(self):
        # Closer matches nearest opener
        assert render("*a *b*") == "*a <em>b</em>"

    def test_strong_inside_emphasis(self):
        assert render("*a **b** c*") == "<em>a <strong>b</strong> c</em>"

    def test_emphasis_inside_strong(self):
        assert render("**a *b* c**") == "<strong>a <em>b</em> c</strong>"

    def test_overlapping_cannot_interleave(self):
        # *a **b* c** should not interleave
        assert render("*a **b* c**") == "<em>a <strong>b</strong></em> c**" or \
               render("*a **b* c**") == "<em>a **b</em> c**"


class TestWhitespaceAndPunctuation:
    """Test whitespace and punctuation definitions."""

    def test_space_after_delimiter_cant_open_em(self):
        # * followed by space isn't left-flanking
        assert render("* test *") == "* test *"

    def test_space_before_delimiter_cant_close_em(self):
        # * preceded by space isn't right-flanking
        assert render("* test *") == "* test *"

    def test_punctuation_after_star_can_open(self):
        # Punctuation counts for flanking rules differently
        # After punctuation, * can still open if other conditions met
        assert render(".*test*.") == ".<em>test</em>."

    def test_no_break_space_as_whitespace(self):
        # U+00A0 no-break space should be treated as whitespace
        assert render("\u00a0*test*") == "\u00a0*test*"


class TestCodeSpanComplexCases:
    """Test complex code span cases."""

    def test_backtick_inside_different_length_code_span(self):
        assert render("``a`b``") == "<code>a`b</code>"

    def test_multiple_backticks_inside_code_span(self):
        assert render("```a``b```") == "<code>a``b</code>"

    def test_code_span_with_all_special_chars(self):
        assert render("`*_~<>&\"`") == "<code>*_~&lt;&gt;&amp;&quot;</code>"

    def test_code_span_first_backtick_unmatched(self):
        # First backtick has no match, stays as plain text
        assert render("`nope") == "`nope"

    def test_code_span_exact_matching(self):
        # Exactly matching backtick runs
        assert render("`````code`````") == "<code>code</code>"

import pytest
from mdinline import render


class TestErrorHandling:
    """Test that newlines and carriage returns raise ValueError."""

    def test_newline_raises_error(self):
        with pytest.raises(ValueError):
            render("one\ntwo")

    def test_carriage_return_raises_error(self):
        with pytest.raises(ValueError):
            render("one\rtwo")

    def test_carriage_return_newline_raises_error(self):
        with pytest.raises(ValueError):
            render("one\r\ntwo")


class TestHTMLEscaping:
    """Test that &, <, >, and " are escaped as entities."""

    @pytest.mark.parametrize("text,expected", [
        ("a & b", "a &amp; b"),
        ("a < b", "a &lt; b"),
        ("a > b", "a &gt; b"),
        ('a " b', 'a &quot; b'),
        ("a & b < c > d", "a &amp; b &lt; c &gt; d"),
        ("&<>\"", "&amp;&lt;&gt;&quot;"),
    ])
    def test_escape_special_chars(self, text, expected):
        assert render(text) == expected

    def test_escape_in_emphasis(self):
        assert render("*a & b*") == "<em>a &amp; b</em>"

    def test_escape_in_code_span(self):
        assert render("`a & b`") == "<code>a &amp; b</code>"


class TestBasicEmphasis:
    """Test simple emphasis cases."""

    @pytest.mark.parametrize("text,expected", [
        ("*hello*", "<em>hello</em>"),
        ("**hello**", "<strong>hello</strong>"),
        ("_hello_", "<em>hello</em>"),
        ("__hello__", "<strong>hello</strong>"),
        ("*Hello* **world**", "<em>Hello</em> <strong>world</strong>"),
    ])
    def test_basic_emphasis(self, text, expected):
        assert render(text) == expected

    def test_nested_emphasis(self):
        assert render("**bold *and* italic**") == "<strong>bold <em>and</em> italic</strong>"

    def test_triple_star(self):
        assert render("***a***") == "<em><strong>a</strong></em>"


class TestCodeSpans:
    """Test code span parsing."""

    @pytest.mark.parametrize("text,expected", [
        ("`code`", "<code>code</code>"),
        ("use `a*b` here", "use <code>a*b</code> here"),
        ("`*asterisk*`", "<code>*asterisk*</code>"),
        ("` ` ", "<code> </code>"),
        ("`` ` ``", "<code> ` </code>"),
        ("`a ` b`", "`a ` b`"),  # No matching closing backtick
        ("```a```", "<code>a</code>"),
        ("````a````", "<code>a</code>"),
    ])
    def test_code_spans(self, text, expected):
        assert render(text) == expected

    def test_code_span_with_leading_trailing_space(self):
        # If content begins and ends with space and is not only spaces, remove one from each end
        assert render("` a `") == "<code>a</code>"
        assert render("`  a  `") == "<code> a </code>"
        assert render("`   `") == "<code>   </code>"  # Only spaces
        assert render("` `") == "<code> </code>"  # Only one space

    def test_code_span_escapes_html(self):
        assert render("`a & b`") == "<code>a &amp; b</code>"
        assert render("`<>`") == "<code>&lt;&gt;</code>"

    def test_code_binds_tighter_than_emphasis(self):
        # From spec: `*a `*` b*` is `<em>a <code>*</code> b</em>`
        assert render("*a `*` b*") == "<em>a <code>*</code> b</em>"


class TestBackslashEscapes:
    """Test backslash escape sequences."""

    @pytest.mark.parametrize("text,expected", [
        (r"\*", "*"),
        (r"\*not emphasis\*", "*not emphasis*"),
        (r"\*a\*", "*a*"),
        (r"\*", "*"),
        (r"\!", "!"),
        (r"\#", "#"),
        (r"\[", "["),
        (r"\]", "]"),
        (r"\\", "\\"),
        (r"\`", "`"),
        (r"\-", "-"),
        (r"\_", "_"),
        (r"\+", "+"),
        (r"\.", "."),
        (r"\(", "("),
        (r"\)", ")"),
        (r"\{", "{"),
        (r"\}", "}"),
        (r"\:", ":"),
        (r"\;", ";"),
        (r"\,", ","),
        (r"\<", "<"),
        (r"\>", ">"),
        (r"\=", "="),
        (r"\&", "&"),
    ])
    def test_escape_ascii_punctuation(self, text, expected):
        assert render(text) == expected

    def test_backslash_before_non_punctuation(self):
        # Backslash before non-punctuation is literal
        assert render(r"\a") == r"\a"
        assert render(r"\1") == r"\1"

    def test_backslash_at_end_of_line(self):
        # Backslash at end is literal
        assert render("a\\") == "a\\"

    def test_escape_inside_code_span(self):
        # Backslashes are always literal inside code spans
        assert render(r"`\*`") == r"<code>\*</code>"
        assert render(r"`\\`") == r"<code>\\</code>"

    def test_escaped_backtick_not_a_backtick_string(self):
        # Escaped backtick is not part of a backtick string
        assert render(r"\` text") == "` text"
        assert render(r"text \`") == "text `"


class TestUnderscoreEmphasis:
    """Test underscore emphasis rules (more restrictive than asterisks)."""

    def test_underscore_inside_word(self):
        # Underscore does not emphasize inside a word
        assert render("snake_case_name") == "snake_case_name"
        assert render("_a_b_") == "_a_b_"

    def test_underscore_at_word_boundary(self):
        # Underscore can open if followed by non-whitespace and non-punctuation (or punctuation with whitespace/punct before)
        # Can close if preceded by non-whitespace and non-punctuation (or punctuation with whitespace/punct after)
        assert render("*a _b_ c*") == "<em>a <em>b</em> c</em>"
        assert render("_foo bar_") == "<em>foo bar</em>"
        assert render("_a b_") == "<em>a b</em>"

    def test_underscore_with_space_before(self):
        # Cannot open if whitespace before (unless punctuation after is also there)
        assert render("a _b") == "a _b"

    def test_underscore_with_space_after(self):
        # Cannot close if whitespace after (unless punctuation before is there)
        assert render("a_") == "a_"


class TestDelimiterMatching:
    """Test delimiter run matching rules."""

    def test_non_matching_delimiter_counts(self):
        # When sum of lengths is multiple of 3, they don't match unless both are multiples of 3
        # From spec: `*foo**bar*` is `<em>foo**bar</em>`
        assert render("*foo**bar*") == "<em>foo**bar</em>"

    def test_triple_delimiter_matching(self):
        # `***a***` - all three are multiples of 3, they match
        assert render("***a***") == "<em><strong>a</strong></em>"

    def test_leftover_delimiters_keep_matching(self):
        # `**a*` - 2 chars from first **, 1 from second *, leftover * stays as plain
        assert render("**a*") == "*<em>a</em>"

    def test_delimiter_mismatch_different_chars(self):
        # * and _ cannot match
        assert render("*a_") == "*a_"

    def test_matching_left_to_right(self):
        # Matching goes left to right over closers
        assert render("**a***b***") == "<strong>a</strong><strong>b</strong>"

    def test_blocked_delimiters(self):
        # Delimiters between matched pairs cannot match anything
        # From spec example: `*foo**bar*` - the middle ** cannot match
        assert render("*foo**bar*") == "<em>foo**bar</em>"


class TestComplexScenarios:
    """Test complex interactions between features."""

    def test_code_breaks_emphasis(self):
        # Code span prevents emphasis matching
        assert render("*a `*` b*") == "<em>a <code>*</code> b</em>"

    def test_escape_backtick_does_not_start_code(self):
        # Escaped backtick is not a backtick string
        assert render(r"\`a\`") == "`a`"

    def test_escape_inside_emphasis(self):
        # Escaped punctuation inside emphasis
        assert render(r"*a\*b*") == "<em>a*b</em>"

    def test_multiple_code_spans(self):
        # Multiple non-overlapping code spans
        assert render("`a` and `b`") == "<code>a</code> and <code>b</code>"

    def test_nested_mixed_emphasis(self):
        # Mixed emphasis nesting
        assert render("***a _b_ c***") == "<em><strong>a <em>b</em> c</strong></em>"

    def test_whitespace_preservation(self):
        # Leading, trailing, and internal whitespace is preserved
        assert render("  hello  ") == "  hello  "
        assert render(" *hello* ") == " <em>hello</em> "

    def test_empty_emphasis(self):
        # Empty emphasis should not be created
        assert render("**") == "**"
        assert render("**a**b**") == "<strong>a</strong>b**"


class TestLeftFlankingAndRightFlanking:
    """Test left-flanking and right-flanking delimiter run rules."""

    def test_asterisk_left_flanking(self):
        # * before non-whitespace and after is non-punct or before is ws/punct
        assert render("*a") == "*a"  # Can open but no closer
